// Same layer update functions, for Reset-by-Subtract
void LIFNeuron_Layer_Update_Subtract(LIFNeuron* neurons, const q7_t* input_spikes, 
                                     const q15_t* weights, uint16_t num_inputs, 
                                     uint16_t num_neurons, q7_t* output_spikes,
                                     const q7_t* recurrent_spikes, const q15_t* recurrent_weights,
                                     uint8_t is_one_to_one) {
    q15_t membrane_potentials[num_neurons];
    q15_t reset_values[num_neurons];
    q15_t decay_factors[num_neurons];
    q15_t thresholds[num_neurons];
    q15_t weighted_inputs[num_neurons];

    // Extract neuron parameters
    for (uint16_t i = 0; i < num_neurons; i++) {
        membrane_potentials[i] = neurons[i].membrane_potential;
        reset_values[i] = neurons[i].reset_value;
        decay_factors[i] = neurons[i].decay_factor;
        thresholds[i] = neurons[i].threshold;
    }

    // Initialize weighted_inputs to zero
    arm_fill_q15(0, weighted_inputs, num_neurons);

    // Calculate weighted input currents (feedforward)
    if (is_one_to_one) {
        // 1-to-1 connection: weights are stored as a vector, each input connects to corresponding neuron
        for (uint16_t i = 0; i < num_inputs && i < num_neurons; i++) {
            if (input_spikes[i]) {
                // For 1-to-1, weight vector: weights[i] corresponds to connection i->i
                arm_add_q15(&weighted_inputs[i], &weights[i], &weighted_inputs[i], 1);
            }
        }
    } else {
        // Fully connected: each input connects to all neurons
        for (uint16_t i = 0; i < num_inputs; i++) {
            if (input_spikes[i]) {
                arm_add_q15(weighted_inputs, &weights[i * num_neurons], weighted_inputs, num_neurons);
            }
        }
    }
    
    // Add recurrent connections (self-connections from previous timestep, always 1-to-1)
    if (recurrent_spikes != NULL && recurrent_weights != NULL) {
        for (uint16_t i = 0; i < num_neurons; i++) {
            if (recurrent_spikes[i]) {
                // Recurrent weights are stored as vector: recurrent_weights[i] for neuron i's self-loop
                arm_add_q15(&weighted_inputs[i], &recurrent_weights[i], &weighted_inputs[i], 1);
            }
        }
    }

    // Vectorized membrane potential update: V = reset + (V - reset) * beta + weighted_input
    // Update membrane for soft reset:
    // v(t+1) = decay * v(t) + weighted_inputs - reset_value(previous step)
    q15_t temp1[num_neurons], temp2[num_neurons];
    
    arm_mult_q15(membrane_potentials, decay_factors, temp1, num_neurons);
    arm_add_q15(temp1, weighted_inputs, temp2, num_neurons);
    arm_sub_q15(temp2, reset_values, membrane_potentials, num_neurons);

    // Spike check, then store reset_value for the NEXT step
    for (uint16_t i = 0; i < num_neurons; i++) {
        if (membrane_potentials[i] > thresholds[i]) {
            output_spikes[i] = 1;
            neurons[i].reset_value = thresholds[i];   // subtract next step
        } else {
            output_spikes[i] = 0;
            neurons[i].reset_value = 0;
        }
        neurons[i].membrane_potential = membrane_potentials[i];

        // Debug print for the most spiking output neuron.
        // if(i == 8){
        //     char buf[200];
        //     snprintf(buf, sizeof(buf), "V:%ld = Reset:%d + acc: %hu| threshold: %d S:%d | nindex = %d \r\n", 
        //             (long)neurons[i].membrane_potential, neurons[i].reset_value, weighted_inputs[i] , neurons[i].threshold, 
        //                 output_spikes[i], i);
        //     usart1_print(buf);
        // }
        
    }
}

void LIFNeuron_Layer_Update_Subtract_NoRecurrent(LIFNeuron* neurons, const q7_t* input_spikes, 
                                                  const q15_t* weights, uint16_t num_inputs, 
                                                  uint16_t num_neurons, q7_t* output_spikes,
                                                  uint8_t is_one_to_one) {
    q15_t membrane_potentials[num_neurons];
    q15_t reset_values[num_neurons];
    q15_t decay_factors[num_neurons];
    q15_t thresholds[num_neurons];
    q15_t weighted_inputs[num_neurons];

    // Extract neuron parameters
    for (uint16_t i = 0; i < num_neurons; i++) {
        membrane_potentials[i] = neurons[i].membrane_potential;
        reset_values[i] = neurons[i].reset_value;
        decay_factors[i] = neurons[i].decay_factor;
        thresholds[i] = neurons[i].threshold;
    }

    // Initialize weighted_inputs to zero
    arm_fill_q15(0, weighted_inputs, num_neurons);

    // Calculate weighted input currents (no recurrent)
    if (is_one_to_one) {
        // 1-to-1 connection: weights are stored as a vector, each input connects to corresponding neuron
        for (uint16_t i = 0; i < num_inputs && i < num_neurons; i++) {
            if (input_spikes[i]) {
                // For 1-to-1, weight vector: weights[i] corresponds to connection i->i
                arm_add_q15(&weighted_inputs[i], &weights[i], &weighted_inputs[i], 1);
            }
        }
    } else {
        // Fully connected: each input connects to all neurons
        for (uint16_t i = 0; i < num_inputs; i++) {
            if (input_spikes[i]) {
                arm_add_q15(weighted_inputs, &weights[i * num_neurons], weighted_inputs, num_neurons);
            }
        }
    }

    // Vectorized membrane potential update
    // Update membrane for soft reset:
    // v(t+1) = decay * v(t) + weighted_inputs - reset_value(previous step)
    q15_t temp1[num_neurons], temp2[num_neurons];
    
    arm_mult_q15(membrane_potentials, decay_factors, temp1, num_neurons);
    arm_add_q15(temp1, weighted_inputs, temp2, num_neurons);
    arm_sub_q15(temp2, reset_values, membrane_potentials, num_neurons);

    // Spike check, then store reset_value for the NEXT step
    for (uint16_t i = 0; i < num_neurons; i++) {
        if (membrane_potentials[i] > thresholds[i]) {
            output_spikes[i] = 1;
            neurons[i].reset_value = thresholds[i];   // subtract next step
        } else {
            output_spikes[i] = 0;
            neurons[i].reset_value = 0;
        }
        neurons[i].membrane_potential = membrane_potentials[i];

        // TODO : Delete this part when the all tests are done.
        // Debug print for the most spiking output neuron.
        // if(i == 8){
        //     char buf[200];
        //     snprintf(buf, sizeof(buf), "V:%ld = Reset:%d + acc: %hu| threshold: %d S:%d | nindex = %d \r\n", 
        //             (long)neurons[i].membrane_potential, neurons[i].reset_value, weighted_inputs[i] , neurons[i].threshold, 
        //                 output_spikes[i], i);
        //     usart1_print(buf);
        // }
        
    }
}



void LIFNeuron_Conv2d_Update_Subtract_CSR(
        LIFNeuron* neurons,           // Array of neurons for this layer
        const q7_t* input_spikes,     // Input feature map, flattened [in_ch*in_h*in_w]
        const q15_t* weights,         // Shared kernel weights [out_ch*in_ch*kh*kw]
        const uint16_t* row_ptr,      // CSR row offsets, length num_inputs + 1
        const uint16_t* out_idx,      // CSR column data: output neuron per connection
        const uint16_t* weight_idx,    // CSR column data: weight index per connection
        uint16_t num_inputs,
        uint16_t num_outputs,
        uint8_t layer_info,            // will hold the which layer is calling for debugging
        q7_t* output_spikes           // Output spikes [out_ch*out_h*out_w]
    ) {

        // DEBUG! 
        float normalized_factor = 60.0f/32767.0f;
        q31_t accumulation = 0;
        float f_accumulation = 0;
        int debug_neuron = 100;
        q15_t V_prev = neurons[debug_neuron].membrane_potential;

        // Decay: V(t+1) = V(t) * beta   (Q15 fixed point)
        for (uint16_t o = 0; o < num_outputs; o++) {
            q31_t decayed = ((q31_t)neurons[o].membrane_potential *
                            (q31_t)neurons[o].decay_factor) >> 15;
            neurons[o].membrane_potential = (q15_t)__SSAT(decayed, 16);
        }
    
        // Event-driven accumulation: only walk rows for inputs that spiked,
        // instead of visiting every (output, kernel-tap) pair unconditionally.
        for (uint16_t i = 0; i < num_inputs; i++) {
            if (input_spikes[i] == 0) {
                continue;
            }
            for (uint16_t c = row_ptr[i]; c < row_ptr[i + 1]; c++) {
                const uint16_t o = out_idx[c];
                const uint16_t  w = weight_idx[c];
                // BCS the ST-MNIST dataset has input spikes other than 0 and 1s the MAC is needed.
                q31_t v = (q31_t)neurons[o].membrane_potential + (q31_t)input_spikes[i] * (q31_t)weights[w];
                neurons[o].membrane_potential = (q15_t)__SSAT(v, 16);

                // DEBUG
                if(layer_info == 2 && o == debug_neuron){
                    accumulation = accumulation + (q31_t)weights[w] * (q31_t)input_spikes[i];
                    f_accumulation = accumulation * normalized_factor;
                }
            }
        }
    
        // Soft reset (subtract previous threshold if it spiked last step) + spike check
        for (uint16_t o = 0; o < num_outputs; o++) {

            neurons[o].membrane_potential -= neurons[o].reset_value;

            if (neurons[o].membrane_potential > neurons[o].threshold) {
                output_spikes[o] = 1;
                neurons[o].reset_value = neurons[o].threshold;  // subtract next step
            } else {
                output_spikes[o] = 0;
                neurons[o].reset_value = 0;
            }
        }

        // TODO: DELETE THIS DEBUG PRINT FROM GENERATOR WHEN ITS FULLY WORKING
        
        // Checking a specific neuron's parameters at every update.
        // output_index = oc * out_h * out_w + oh * out_w + ow
        // The most spiking neuron of the first layer is:   Channel = 7, Y = 3, X = 0
        // So 7 * 7 * 7 + 3 * 7 + 0 = 364 

        // Most spiking Layer 2 neuron:
        // Channel = 11, Y = 0, X = 1
        // 11 * 3 * 3 + 0 + 1 = 100

        // if(layer_info == 2){
        //     print_float("Normalized V: ", (long)neurons[debug_neuron].membrane_potential * normalized_factor);
        //     print_float("Normalized Accumulation V: ", f_accumulation);
        //     // char buf[200];
        //     // // Use %ld for q31_t (long int) to avoid format warnings
        //     // // We print the raw integer. 60 = 1.0 in float terms.
        //     // snprintf(buf, sizeof(buf), "V:%ld | Reset:%ld | threshold: %d | S:%d | nindex = %d | v_prev = %ld | decay = %ld \r\n", 
        //     //         (long)neurons[debug_neuron].membrane_potential, neurons[debug_neuron].reset_value, neurons[debug_neuron].threshold, 
        //     //         output_spikes[debug_neuron], debug_neuron, V_prev, neurons[debug_neuron].decay_factor);
        //     // usart1_print(buf);
        // }


        
    }

